import zipfile
p='inputs/scogs_fungi.zip'
with zipfile.ZipFile(p) as z:
    ns=sorted(n for n in z.namelist() if n.endswith('.mafft'))
    print('mafft_count',len(ns))
    for n in ns[:3]:
        txt=z.read(n).decode()
        seqs=[]
        cur=''
        heads=[]
        for line in txt.splitlines():
            if line.startswith('>'):
                if heads: seqs.append(cur)
                heads.append(line[1:].split()[0]); cur=''
            else: cur+=line.strip()
        if heads: seqs.append(cur)
        print(n,'seqs',len(seqs),'lengths',sorted(set(map(len,seqs))),'headers',heads)
